using ChessboardTactics.Core;
using UnityEngine;

namespace ChessboardTactics.Game
{
    /// <summary>Every material, clip and unit description the game uses; generated by the editor ProjectBuilder.</summary>
    public sealed class GameArt : ScriptableObject
    {
        [Header("Board")]
        public Material LightTile;
        public Material DarkTile;
        public Material Frame;
        public Material Trim;
        public Material Table;
        public Material Rock;
        public Material RockDark;

        [Header("Highlights (transparent, unlit)")]
        public Material MoveHighlight;
        public Material AttackHighlight;
        public Material ThreatHighlight;
        public Material SelectHighlight;
        public Material HoverHighlight;

        [Header("Armies")]
        public Material PlayerBody;
        public Material PlayerAccent;
        public Material EnemyBody;
        public Material EnemyAccent;
        public Material Gold;
        public Material BarBack;
        public Material BarFill;

        [Header("Meshes (Unity's built-in shapes, referenced so builds include them)")]
        public Mesh CubeMesh;
        public Mesh SphereMesh;
        public Mesh CylinderMesh;
        public Mesh CapsuleMesh;
        public Mesh QuadMesh;

        [Header("Effects")]
        public Material ParticleAdditive;
        public Material ParticleAlpha;

        [Header("Units")]
        public WarriorData[] Warriors;

        [Header("Audio")]
        public AudioClip BattleMusic;
        public AudioClip CampMusic;
        public AudioClip Select;
        public AudioClip Move;
        public AudioClip Slash;
        public AudioClip Bolt;
        public AudioClip UnitDown;
        public AudioClip Promote;
        public AudioClip TurnPlayer;
        public AudioClip TurnEnemy;
        public AudioClip Victory;
        public AudioClip Defeat;
        public AudioClip Click;
        public AudioClip Invalid;

        public WarriorData Warrior(PieceType type)
        {
            foreach (WarriorData warrior in Warriors)
            {
                if (warrior != null && warrior.CharacterType == type)
                {
                    return warrior;
                }
            }
            return null;
        }

        public string NameOf(Unit unit)
        {
            WarriorData warrior = Warrior(unit.Type);
            return warrior != null ? warrior.NameFor(unit.Team) : unit.Stats.Name;
        }
    }
}
